import java.util.List;
import java.util.Random;

/**
  * A simple model of a seaweed.
 * 
 * Seaweed age, consume oxygen during the night and produce oxygen during the daytime, propogate, 
 * and may die of that or of weather.
 *
 * @version 2022/03/02
 */
public class Seaweed extends Creature
{

    // The age at which a seaweed becomes mature and could be edible.
    private static final int MATURE_AGE = 20;
    // The age to which a shrimp can live.
    private static final int MAX_AGE = 40;
    // The likelihood of a seaweed propagate.
    private static final double PROPAGATE_PROBABILITY = 0.05;
    // The maximum number of births.
    private static final int MAX_PROPAGATE_SIZE = 1;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    // The amount of oxygen a plant need to survive in night.
    private static final double PLANT_OXYGEN_REQUIRED = 0.00000002;
    // The amount of oxygen a plant generated during day time.
    private static final double OXYGEN_GENERATED = 0.0000005;


    // Individual characteristics (instance fields).

    // The seaweed's age.
    private int age;

    /**
     * Constructor for objects of class Seaweed
     */
    public Seaweed(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        age = 0;
        if(randomAge) {
            age = rand.nextInt(MAX_AGE);
        }  
    }

   /**
     * This is what the seawead does most of the time - stay motionlessly under the water
     * @param newSeaweeds A list to return newly born shrimps.
     * @param atDayTime true if current step is daytime false otherwise.
     * @param oxygenLevel The inital level of dissolved oxygen in the water.
     * @param disease The disease may happened during simulation.  
     * @param step current step.
     * 
     * @return the oxygen level the species produced or consumed after action.
     */
    public double act(List<Creature> newSeaweeds, boolean atDayTime, double oxygenLevel, Disease disease,  int step)
    {
        incrementAge();
        if(oxygenLevel < PLANT_OXYGEN_REQUIRED){
            setDead();
            return 0;
        }    


        if(isAlive()){
            if(age >= MATURE_AGE)
                giveBirth(newSeaweeds);            
            }


        if(atDayTime)
            return OXYGEN_GENERATED;
        else
            return -PLANT_OXYGEN_REQUIRED;
        }

    /**
     * Increase the age.
     * This could result in the shrimp's death.
     */
    private void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }

    /**
     * Check whether or not this shrimp is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newSeaweeds A list to return newly propagated seaweed.
     */
    private void giveBirth(List<Creature> newSeaweeds)
    {
        // New seaweed are created into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());

        for(int b = 0; free.size() > 0; b++) {
            Location loc = free.remove(0);
            Seaweed young = new Seaweed(false, field, loc);
            newSeaweeds.add(young);
        }
    }
}

import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing Seaweed, Salmon, Cod, Shark, Whale, and also the elmement of disease and weather
 *
 * @version 2022/03/02
 */
public class Simulator
{
    // Constants representing configuration information for the simulation.
    // The default width for the grid.
    private static final int DEFAULT_WIDTH = 120;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 80;

    // The probability that a fox will be created in any given grid position.
    private static final double SALMON_CREATION_PROBABILITY = 0.08;
    // The probability that a rabbit will be created in any given grid position.
    private static final double COD_CREATION_PROBABILITY = 0.08;  
    // The probability that a seaweed will be created in any given grid position.
    private static final double SEAWEED_CREATION_PROBABILITY = 0.03;
    // The probability that a shark will be created in any given grid position.
    private static final double SHARK_CREATION_PROBABILITY = 0.04;
    // The probability that a whale will be created in any given grid position.
    private static final double WHALE_CREATION_PROBABILITY = 0.03;

    // The probability that a storm may occur.
    private static final double STORM_HAPPEN_PROBABILITY = 0.14; 


    // List of creatures in the field.
    private List<Creature> creatures;
    // The current state of the field.
    private Field field;
    // The current step of the simulation.
    private int step;
    // A graphical view of the simulation.
    private SimulatorView view;
    private Disease disease;
    private Weather weather;


    // The inital level of dissolved oxygen in the water. 
    private double oxygenLevel; 

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        creatures = new ArrayList<>();

        field = new Field(depth, width);
        weather = new Weather(field);
        disease = new Disease();

        oxygenLevel = 1;


        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width);

        view.setColor(Cod.class, Color.ORANGE);
        view.setColor(Salmon.class, Color.YELLOW);
        view.setColor(Seaweed.class, Color.RED);
        view.setColor(Shark.class, Color.BLACK);
        view.setColor(Whale.class, Color.PINK);
        view.setColor(Weather.class,Color.BLUE);

        // Setup a valid starting point.
        reset();
    }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (1000 steps).
     */
    public void runLongSimulation()
    {
        simulate(1000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            delay(60);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * 
     * Iterate over the whole field updating the state of each
     * creaturesÃ¯Â¼Ârecord the total amount of oxygen that is consumed or produced 
     * by specific species in each step, Storms have a certain probability of occurring�, 
     * update the oxygen level, and identify if the disease is stops.
     */
    public void simulateOneStep()
    {
        step++;

        double totalOxygenInvolved= 0; //oxygen that is generated or consumed in total for this step

        disease.tryToStartSpread(creatures, step);

        // Provide space for newborn animals.
        List<Creature> newCreatures = new ArrayList<>();        
        // Let all creatures act.
        for(Iterator<Creature> it = creatures.iterator(); it.hasNext(); ) {
            Creature creature = it.next();
            totalOxygenInvolved += creature.act(newCreatures, timeOfDay(), oxygenLevel, disease, step);
            if(!creature.isAlive()) {
                it.remove();
            }
        }

        if(Randomizer.getRandom().nextDouble() <= STORM_HAPPEN_PROBABILITY) {
            weather.underwaterStorm(3); //  generate the storm at a random location.
            weather.setStormStart(true);
        } else {
            weather.setStormStart(false);
        }        

        // calculate the oxygen left
        oxygenLevel += totalOxygenInvolved;

        // identify if disease stops
        if(disease.getIsSpread()){
            disease.setIsSpread(hasActiveInfections());
        }

        // Add the newly born creatures to the main lists.
        creatures.addAll(newCreatures);
        view.showStatus(step, field, timeOfDay(), weather, oxygenLevel);
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        creatures.clear();
        populate();
        oxygenLevel = 1;
        Animal.populationDieOfDisease = 0;

        // Show the starting state in the view.
        view.showStatus(step, field, timeOfDay(), weather, oxygenLevel);
    }

    /**
     * Randomly populate the field with Salmon, Seaweed, Shark and Whale.
     * notice if and else if is based on the creation probability of a creature in an ascending order
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                addCreature(createRandomCreature(rand, new Location(row, col)));
            }
        }
    }

    /**
     *  Pause for a given time.
     *  @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }

    /**
     * 5 steps is considered as a day time followed by 5 steps considered as a night.
     * 
     * @return true If currently step is day time false if it is night time.
     */
    public boolean timeOfDay(){
        return (step % 10) < 5;
    }

    /**
     *  If all animals infected die or all animals get immunity, the disease stops.
     *  Only animal can be infected.
     */
    public boolean hasActiveInfections(){
        for(Creature creature : creatures) {
            if(creature instanceof Animal) {
                Animal animal = (Animal) creature;
                if(animal.getIsInfected() && !animal.getIsImmuned()) {
                    return true;
                }
            }
        }
        return false;
    }

    private void addCreature(Creature creature)
    {
        if(creature != null) {
            creatures.add(creature);
        }
    }

    private Creature createRandomCreature(Random rand, Location location)
    {
        if(rand.nextDouble() <= SALMON_CREATION_PROBABILITY) {
            return new Salmon(true, field, location);
        }
        else if(rand.nextDouble() <= COD_CREATION_PROBABILITY) {
            return new Cod(true, field, location);
        }
        else if(rand.nextDouble() <= SEAWEED_CREATION_PROBABILITY) {
            return new Seaweed(true, field, location);
        }
        else if(rand.nextDouble() <= SHARK_CREATION_PROBABILITY) {
            return new Shark(true, field, location);
        }
        else if(rand.nextDouble() <= WHALE_CREATION_PROBABILITY) {
            return new Whale(true, field, location);
        }
        return null;
    }
}

import java.awt.*;
import javax.swing.*;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.List;


/**
 * A graphical view of the simulation grid.
 * The view displays a colored rectangle for each location 
 * representing its contents. It uses a default background color.
 * Colors for each type of species can be defined using the
 * setColor method.
 *
 * @version 2022/03/02
 */
public class SimulatorView extends JFrame
{
    // Colors used for empty locations.
    private static final Color EMPTY_COLOR = Color.white;

    // Color used for objects that have no defined color.
    private static final Color UNKNOWN_COLOR = Color.gray;

    // Colour used for objects that are infected by disease;
    private static final Color INFECTED_COLOR = Color.green;


    private final String STEP_PREFIX = "Step: ";
    private final String POPULATION_PREFIX = "Population: ";
    private final String DAYOFTIME_PREFIX = "Time: It's ";
    private final String POPULATION_DIE_OF_DISEASE_PREFIX = "Population died of disease: ";


    private JLabel stepLabel, population, infoLabel, diseaseLabel;
    private FieldView fieldView;

    // A map for storing colors for participants in the simulation
    private Map<Class<?>, Color> colors;
    // A statistics object computing and storing simulation information
    private FieldStats stats;

    /**
     * Create a view of the given width and height.
     * @param height The simulation's height.
     * @param width  The simulation's width.
     */
    public SimulatorView(int height, int width)
    {
        stats = new FieldStats();
        colors = new LinkedHashMap<>();

        setTitle("Underwater Environment Simulation");
        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
        infoLabel = new JLabel(DAYOFTIME_PREFIX + " ", JLabel.CENTER);
        diseaseLabel = new JLabel(POPULATION_DIE_OF_DISEASE_PREFIX, JLabel.CENTER);

        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);

        setLocation(100, 50);

        fieldView = new FieldView(height, width);

        Container contents = getContentPane();

        JPanel infoPane = new JPanel(new BorderLayout());
        infoPane.add(stepLabel, BorderLayout.WEST);
        infoPane.add(infoLabel, BorderLayout.CENTER);
        infoPane.add(diseaseLabel, BorderLayout.EAST);
        contents.add(infoPane, BorderLayout.NORTH);
        contents.add(fieldView, BorderLayout.CENTER);
        contents.add(population, BorderLayout.SOUTH);
        pack();
        setVisible(true);
    }



    /**
     * Define a color to be used for a given class of animal.
     * @param animalClass The animal's Class object.
     * @param color The color to be used for the given class.
     */
    public void setColor(Class<?> animalClass, Color color)
    {
        colors.put(animalClass, color);
    }

    /**
     * Display a short information label at the top of the window.
     */
    public void setInfoText(String text)
    {
        infoLabel.setText(text);
    }

    /**
     * @return The color to be used for a given class of animal.
     */
    private Color getColor(Class<?> animalClass)
    {
        Color col = colors.get(animalClass);
        if(col == null) {
            // no color defined for this class
            return UNKNOWN_COLOR;
        }
        else {
            return col;
        }
    }

    /**
     * Show the current status of the field.
     * @param step Which iteration step it is.
     * @param field The field whose status is to be displayed.
     * @param weather the object of weather class
     * @param oxygenLevel the oxygen level that is to be displayed in the current step.
     */
    public void showStatus(int step, Field field, boolean timeOfDay, Weather weather, double oxygenLevel)
    {
         if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        infoLabel.setText("It is: " + (timeOfDay? "daytime": "night ") 
                            + "        Oxygen Level: " + (int)(oxygenLevel * 100) + "%"
                            + "        Storm: " + (weather.getStormStart()? "exists": "subsides"));
        diseaseLabel.setText(POPULATION_DIE_OF_DISEASE_PREFIX + Animal.populationDieOfDisease);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Creature creature = field.getCreatureAt(row, col);
                if(creature != null && weather.getStormStart() == false) {
                    stats.incrementCount(creature.getClass());
                    if(creature instanceof Animal){
                     Animal ani = (Animal)creature;
                        if(ani.getIsInfected() && !ani.getIsImmuned())
                            fieldView.drawMark(col, row, INFECTED_COLOR);
                        else 
                            fieldView.drawMark(col, row, getColor(creature.getClass()));
                    }
                    else
                        fieldView.drawMark(col, row, getColor(creature.getClass()));
                }
                else if(creature != null && weather.getStormStart() == true) {
                    stats.incrementCount(creature.getClass());
                    fieldView.drawMark(col, row, getColor(creature.getClass())); 
                    drawStormColor(field, weather);
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }   

            }
        }



        stats.countFinished();
        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

    /**
     * Determine whether the simulation should continue to run.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        return stats.isViable(field);
    }

    /**
     * Draw the colour of the storm, and the range of the storm is given by storm scope of 
     * the object of Weather class.
     * 
     * @param field The field where the weather might happen and to be displayed.
     * @param weather the object of Weather class
     */
    private void drawStormColor(Field field, Weather weather) {
        List<Location> stormLocation = field.adjacentLocationsIncludingSelf(weather.getRandomLocation(),weather.getStormScope());
        for(Location location : stormLocation) {
            fieldView.drawMark(location.getCol(),location.getRow(),getColor(Weather.class));
        }

    }


    /**
     * Provide a graphical view of a rectangular field. This is 
     * a nested class (a class defined inside a class) which
     * defines a custom component for the user interface. This
     * component displays the field.
     * This is rather advanced GUI stuff - you can ignore this 
     * for your project if you like.
     */
    private class FieldView extends JPanel
    {
        private final int GRID_VIEW_SCALING_FACTOR = 6;

        private int gridWidth, gridHeight;
        private int xScale, yScale;
        Dimension size;
        private Graphics g;
        private Image fieldImage;

        /**
         * Create a new FieldView component.
         */
        public FieldView(int height, int width)
        {
            gridHeight = height;
            gridWidth = width;
            size = new Dimension(0, 0);
        }

        /**
         * Tell the GUI manager how big we would like to be.
         */
        public Dimension getPreferredSize()
        {
            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
        }



        /**
         * Prepare for a new round of painting. Since the component
         * may be resized, compute the scaling factor again.
         */
        public void preparePaint()
        {
            if(! size.equals(getSize())) {  // if the size has changed...
                size = getSize();
                fieldImage = fieldView.createImage(size.width, size.height);
                g = fieldImage.getGraphics();

                xScale = size.width / gridWidth;
                if(xScale < 1) {
                    xScale = GRID_VIEW_SCALING_FACTOR;
                }
                yScale = size.height / gridHeight;
                if(yScale < 1) {
                    yScale = GRID_VIEW_SCALING_FACTOR;
                }
            }
        }

        /**
         * Paint on grid location on this field in a given color.
         */
        public void drawMark(int x, int y, Color color)
        {
            g.setColor(color);
            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
        }

        /**
         * The field view component needs to be redisplayed. Copy the
         * internal image to screen.
         */
        public void paintComponent(Graphics g)
        {
            if(fieldImage != null) {
                Dimension currentSize = getSize();
                if(size.equals(currentSize)) {
                    g.drawImage(fieldImage, 0, 0, null);
                }
                else {
                    // Rescale the previous image.
                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
                }
            }
        }
    }
}

import java.util.HashMap;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 2022/03/02
 */
public class FieldStats
{
    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
    private HashMap<Class<?>, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        // Set up a collection for counters for each type of animal that
        // we might find
        counters = new HashMap<>();
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * @return A string describing what is in the field.
     */
    public String getPopulationDetails(Field field)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class<?> key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(Class<?> key : counters.keySet()) {
            Counter count = counters.get(key);
            count.reset();
        }
    }



    /**
     * Increment the count for one class of animal.
     * @param animalClass The class of animal to increment.
     */
    public void incrementCount(Class<?> animalClass)
    {
        Counter count = counters.get(animalClass);
        if(count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(animalClass.getName());
            counters.put(animalClass, count);
        }
        count.increment();
    }

    /**
     * Indicate that an animal count has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class<?> key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

    /**
     * Generate counts of the number of foxes and rabbits.
     * These are not kept up to date as foxes and rabbits
     * are placed in the field, but only when a rrandomAdjacentLocationequest
     * is made for the information.
     * @param field The field to generate the stats for.
     */
    private void generateCounts(Field field)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Creature animal = field.getCreatureAt(row, col);
                if(animal != null) {
                    incrementCount(animal.getClass());
                }
            }
        }
        countsValid = true;
    }
}

import java.util.Random;
import java.util.List;

/**
 * A simple model of a cod.
 * 
 * Cods age, move, eat seaweed, consume oxygen, propogate, 
 * and may get infected by disease and die of that or of weather.
 *
 * @version 2022/03/02
 */
public class Cod extends Animal
{
    // Characteristics shared by all cods (class variables).

    // The age at which a cod can start to breed.
    private static final int BREEDING_AGE = 6;
    // The age to which a cod can live.
    private static final int MAX_AGE = 50;
    // The likelihood of a cod breeding.
    private static final double BREEDING_PROBABILITY = 0.3;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 10;

    // The food value of a cod. In effect, this is the
    // number of steps a cod can go before it has to eat again.
    private static final int SEAWEED_FOOD_VALUE = 13;

    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    // Individual characteristics (instance fields).

    // The cod's age.
    private int age;

    // THe cod's food level
    private int foodLevel;

    /**
     * Create a new cod. A cod may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the cod will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Cod(boolean randomAge, Field field, Location location)
    {
        super(field, location);

        if(randomAge) {
            age = rand.nextInt(MAX_AGE);
            foodLevel = rand.nextInt(SEAWEED_FOOD_VALUE);
        }
        else {
            age = 0;
            foodLevel = SEAWEED_FOOD_VALUE;
        }
    }

    /**
     * This is what the cod does most of the time - it runs 
     * around. Sometimes it will breed or die of old age.
     * 
     * @param newCods A list to return newly born cods.
     * @param atDayTime true if current step is daytime false otherwise.
     * @param oxygenLevel The inital level of dissolved oxygen in the water.
     * @param disease The disease may happened during simulation.  
     * @param step current step.
     * 
     * @return the oxygen level the species produced or consumed after action.
     * 
     */
    protected void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }

    /**
     * Make this cod more hungry. This could result in the cod's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Check whether or not this cod is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newCods A list to return newly born cods.

     */
    protected void giveBirth(List<Creature> newCod)
    {
        // New cods are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
