  7	/**
  8	 * A simple predator-prey simulator, based on a rectangular field
  9	 * containing Seaweed, Salmon, Cod, Shark, Whale, and also the elmement of disease and weather
 10	 *
 11	 * @version 2022/03/02
 12	 */
 13	public class Simulator
 14	{
 15	    private interface CreatureSpawner
 16	    {
 17	        Creature create(Location location);
 18	    }
 19	
 20	    private static class PopulationSeed
 21	    {
 22	        private double creationProbability;
 23	        private CreatureSpawner spawner;
 24	
 25	        PopulationSeed(double creationProbability, CreatureSpawner spawner)
 26	        {
 27	            this.creationProbability = creationProbability;
 28	            this.spawner = spawner;
 29	        }
 30	
 31	        boolean shouldCreate(Random random)
 32	        {
 33	            return random.nextDouble() <= creationProbability;
 34	        }
 35	
 36	        Creature create(Location location)
 37	        {
 38	            return spawner.create(location);
 39	        }
 40	    }
 41	
 42	    // Constants representing configuration information for the simulation.
 43	    private static final int DEFAULT_WIDTH = 120;
 44	    private static final int DEFAULT_DEPTH = 80;
 45	    private static final int LONG_SIMULATION_STEPS = 1000;
 46	    private static final int DAY_LENGTH = 5;
 47	    private static final int FULL_DAY_LENGTH = DAY_LENGTH * 2;
 48	    private static final int STORM_SCOPE = 3;
 49	
 50	    // The probability that a species will be created in any given grid position.
 51	    private static final double SALMON_CREATION_PROBABILITY = 0.08;
 52	    private static final double COD_CREATION_PROBABILITY = 0.08;
 53	    private static final double SEAWEED_CREATION_PROBABILITY = 0.03;
 54	    private static final double SHARK_CREATION_PROBABILITY = 0.04;
 55	    private static final double WHALE_CREATION_PROBABILITY = 0.03;
 56	
 57	    // The probability that a storm may occur.
 58	    private static final double STORM_HAPPEN_PROBABILITY = 0.14;
 59	
 60	    // List of creatures in the field.
 61	    private List<Creature> creatures;
 62	    // The current state of the field.
 63	    private Field field;
 64	    // The current step of the simulation.
 65	    private int step;
 66	    // A graphical view of the simulation.
 67	    private SimulatorView view;
 68	    private Disease disease;
 69	    private Weather weather;
 70	    private PopulationSeed[] populationSeeds;
 71	
 72	    // The inital level of dissolved oxygen in the water.
 73	    private double oxygenLevel;
 74	
 75	    /**
 76	     * Construct a simulation field with default size.
 77	     */
 78	    public Simulator()
 79	    {
 80	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
 81	    }
 82	
 83	    /**
 84	     * Create a simulation field with the given size.
 85	     * @param depth Depth of the field. Must be greater than zero.
 86	     * @param width Width of the field. Must be greater than zero.
 87	     */
 88	    public Simulator(int depth, int width)
 89	    {
 90	        int[] dimensions = sanitizeDimensions(depth, width);
 91	        creatures = new ArrayList<>();
 92	        field = new Field(dimensions[0], dimensions[1]);
 93	        weather = new Weather(field);
 94	        disease = new Disease();
 95	        oxygenLevel = 1;
 96	
 97	        initializePopulationSeeds();
 98	        initializeView(dimensions[0], dimensions[1]);
 99	        reset();
100	    }
101	
102	    /**
103	     * Run the simulation from its current state for a reasonably long period.
104	     */
105	    public void runLongSimulation()
106	    {
107	        simulate(LONG_SIMULATION_STEPS);
108	    }
109	
110	    /**
111	     * Run the simulation from its current state for the given number of steps.
112	     * Stop before the given number of steps if it ceases to be viable.
113	     * @param numSteps The number of steps to run for.
114	     */
115	    public void simulate(int numSteps)
116	    {
117	        for(int simulatedSteps = 0; simulatedSteps < numSteps && view.isViable(field); simulatedSteps++) {
118	            simulateOneStep();
119	            delay(60);
120	        }
121	    }
122	
123	    /**
124	     * Run the simulation from its current state for a single step.
125	     */
126	    public void simulateOneStep()
127	    {
128	        step++;
129	        disease.tryToStartSpread(creatures, step);
130	
131	        List<Creature> newCreatures = new ArrayList<>();
132	        double oxygenChange = actForAllCreatures(newCreatures);
133	
134	        updateStormState();
135	        oxygenLevel += oxygenChange;
136	        updateDiseaseState();
137	        creatures.addAll(newCreatures);
138	        showStatus();
139	    }
140	
141	    /**
142	     * Reset the simulation to a starting position.
143	     */
144	    public void reset()
145	    {
146	        step = 0;
147	        creatures.clear();
148	        populate();
149	        oxygenLevel = 1;
150	        Animal.populationDieOfDisease = 0;
151	        showStatus();
152	    }
153	
154	    /**
155	     * 5 steps is considered as a day time followed by 5 steps considered as a night.
156	     *
157	     * @return true If currently step is day time false if it is night time.
158	     */
159	    public boolean timeOfDay()
160	    {
161	        return (step % FULL_DAY_LENGTH) < DAY_LENGTH;
162	    }
163	
164	    /**
165	     * If all animals infected die or all animals get immunity, the disease stops.
166	     * Only animal can be infected.
167	     */
168	    public boolean hasActiveInfections()
169	    {
170	        for(Creature creature : creatures) {
171	            if(creature instanceof Animal) {
172	                Animal animal = (Animal) creature;
173	                if(animal.getIsInfected() && !animal.getIsImmuned()) {
174	                    return true;
175	                }
176	            }
177	        }
178	        return false;
179	    }
180	
181	    private int[] sanitizeDimensions(int depth, int width)
182	    {
183	        if(width <= 0 || depth <= 0) {
184	            System.out.println("The dimensions must be greater than zero.");
185	            System.out.println("Using default values.");
186	            return new int[]{DEFAULT_DEPTH, DEFAULT_WIDTH};
187	        }
188	        return new int[]{depth, width};
189	    }
190	
191	    private void initializePopulationSeeds()
192	    {
193	        populationSeeds = new PopulationSeed[]{
194	            new PopulationSeed(SALMON_CREATION_PROBABILITY, location -> new Salmon(true, field, location)),
195	            new PopulationSeed(COD_CREATION_PROBABILITY, location -> new Cod(true, field, location)),
196	            new PopulationSeed(SEAWEED_CREATION_PROBABILITY, location -> new Seaweed(true, field, location)),
197	            new PopulationSeed(SHARK_CREATION_PROBABILITY, location -> new Shark(true, field, location)),
198	            new PopulationSeed(WHALE_CREATION_PROBABILITY, location -> new Whale(true, field, location))
199	        };
200	    }
201	
202	    private void initializeView(int depth, int width)
203	    {
204	        view = new SimulatorView(depth, width);
205	        view.setColor(Cod.class, Color.ORANGE);
206	        view.setColor(Salmon.class, Color.YELLOW);
207	        view.setColor(Seaweed.class, Color.RED);
208	        view.setColor(Shark.class, Color.BLACK);
209	        view.setColor(Whale.class, Color.PINK);
210	        view.setColor(Weather.class, Color.BLUE);
211	    }
212	
213	    private double actForAllCreatures(List<Creature> newCreatures)
214	    {
215	        double oxygenChange = 0;
216	        boolean atDayTime = timeOfDay();
217	        for(Iterator<Creature> iterator = creatures.iterator(); iterator.hasNext(); ) {
218	            Creature creature = iterator.next();
219	            oxygenChange += creature.act(newCreatures, atDayTime, oxygenLevel, disease, step);
220	            if(!creature.isAlive()) {
221	                iterator.remove();
222	            }
223	        }
224	        return oxygenChange;
225	    }
226	
227	    private void updateStormState()
228	    {
229	        if(Randomizer.getRandom().nextDouble() <= STORM_HAPPEN_PROBABILITY) {
230	            weather.underwaterStorm(STORM_SCOPE);
231	            weather.setStormStart(true);
232	        }
233	        else {
234	            weather.setStormStart(false);
235	        }
236	    }
237	
238	    private void updateDiseaseState()
239	    {
240	        if(disease.getIsSpread()) {
241	            disease.setIsSpread(hasActiveInfections());
242	        }
243	    }
244	
245	    private void showStatus()
246	    {
247	        view.showStatus(step, field, timeOfDay(), weather, oxygenLevel);
248	    }
249	
250	    /**
251	     * Randomly populate the field with Salmon, Seaweed, Shark and Whale.
252	     * notice if and else if is based on the creation probability of a creature in an ascending order
253	     */
254	    private void populate()
255	    {
256	        Random random = Randomizer.getRandom();
257	        field.clear();
258	        for(int row = 0; row < field.getDepth(); row++) {
259	            for(int col = 0; col < field.getWidth(); col++) {
260	                addCreature(createRandomCreature(random, new Location(row, col)));
261	            }
262	        }
263	    }
264	
265	    /**
266	     *  Pause for a given time.
267	     *  @param millisec  The time to pause for, in milliseconds
268	     */
269	    private void delay(int millisec)
270	    {
271	        try {
272	            Thread.sleep(millisec);
273	        }
274	        catch (InterruptedException ie) {
275	            // wake up
276	        }
277	    }
278	
279	    private void addCreature(Creature creature)
280	    {
281	        if(creature != null) {
282	            creatures.add(creature);
283	        }
284	    }
285	
286	    private Creature createRandomCreature(Random random, Location location)
287	    {
288	        for(PopulationSeed populationSeed : populationSeeds) {
289	            if(populationSeed.shouldCreate(random)) {
290	                return populationSeed.create(location);
291	            }
292	        }
293	        return null;
294	    }
295	}

