201	     * a nested class (a class defined inside a class) which
202	     * defines a custom component for the user interface. This
203	     * component displays the field.
204	     * This is rather advanced GUI stuff - you can ignore this
205	     * for your project if you like.
206	     */
207	    private class FieldView extends JPanel
208	    {
209	        private static final int GRID_VIEW_SCALING_FACTOR = 6;
210	
211	        private int gridWidth;
212	        private int gridHeight;
213	        private int xScale;
214	        private int yScale;
215	        private Dimension size;
216	        private Graphics graphics;
217	        private Image fieldImage;
218	
219	        /**
220	         * Create a new FieldView component.
221	         */
222	        FieldView(int height, int width)
223	        {
224	            gridHeight = height;
225	            gridWidth = width;
226	            size = new Dimension(0, 0);
227	        }
228	
229	        /**
230	         * Tell the GUI manager how big we would like to be.
231	         */
232	        public Dimension getPreferredSize()
233	        {
234	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
235	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
236	        }
237	
238	        /**
239	         * Prepare for a new round of painting. Since the component
240	         * may be resized, compute the scaling factor again.
241	         */
242	        public void preparePaint()
243	        {
244	            if(!size.equals(getSize())) {
245	                size = getSize();
246	                fieldImage = fieldView.createImage(size.width, size.height);
247	                graphics = fieldImage.getGraphics();
248	
249	                xScale = size.width / gridWidth;
250	                if(xScale < 1) {
251	                    xScale = GRID_VIEW_SCALING_FACTOR;
252	                }
253	                yScale = size.height / gridHeight;
254	                if(yScale < 1) {
255	                    yScale = GRID_VIEW_SCALING_FACTOR;
256	                }
257	            }
258	        }
259	
260	        /**
261	         * Paint on grid location on this field in a given color.
262	         */
263	        public void drawMark(int x, int y, Color color)
264	        {
265	            graphics.setColor(color);
266	            graphics.fillRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
267	        }
268	
269	        /**
270	         * The field view component needs to be redisplayed. Copy the
271	         * internal image to screen.
272	         */
273	        public void paintComponent(Graphics graphics)
274	        {
275	            super.paintComponent(graphics);
276	            if(fieldImage != null) {
277	                Dimension currentSize = getSize();
278	                if(size.equals(currentSize)) {
279	                    graphics.drawImage(fieldImage, 0, 0, null);
280	                }
281	                else {
282	                    graphics.drawImage(fieldImage, 0, 0,
283	                                       currentSize.width, currentSize.height, null);
284	                }
285	            }
286	        }
287	    }
288	}

