 22	    
 23	    
 24	    /**
 25	     * Create a new creature at location in field.
 26	     * 
 27	     * @param field The field currently occupied.
 28	     * @param location The location within the field.
 29	     */
 30	    public Creature(Field field, Location location)
 31	    {
 32	        alive = true;
 33	        this.field = field;
 34	        setLocation(location);
 35	    }
 36	    
 37	    /**
 38	     * Make this creature act - that is: make it do
 39	     * whatever it wants/needs to do.
 40	     * @param newCreatures A list to receive newly born creatures.
 41	     * @param atDayTime true if current step is daytime false otherwise.
 42	     * @param oxygenLevel The inital level of dissolved oxygen in the water.
 43	     * @param disease The disease may happened during simulation.  
 44	     * @param step current step.
 45	     * 
 46	     * @return the oxygen level the species produced or consumed after action.
 47	     */
 48	    abstract public double act(List<Creature> newCreatures, boolean atDayTime, double oxygenLevel, Disease disease, int step);
 49	
 50	    /**
 51	     * Check whether the creature is alive or not.
 52	     * @return true if the creature is still alive.
 53	     */
 54	    protected boolean isAlive()
 55	    {
 56	        return alive;
 57	    }
 58	    
 59	      /**
 60	     * Indicate that the creature is no longer alive.
 61	     * It is removed from the field.
 62	     */
 63	    protected void setDead()
 64	    {
 65	        alive = false;
 66	        if(location != null) {
 67	            field.clear(location);
 68	            location = null;
 69	            field = null;
 70	        }
 71	    }
 72	
 73	    /**
 74	     * Return the creature's location.
 75	     * @return The creature's location.
 76	     */
 77	    protected Location getLocation()
 78	    {
 79	        return location;
 80	    }
 81	    
 82	    /**
 83	     * Place the creature at the new location in the given field.
 84	     * @param newLocation The creature's new location.
 85	     */
 86	    protected void setLocation(Location newLocation)
 87	    {
 88	        if(location != null) {
 89	            field.clear(location);
 90	        }
 91	        location = newLocation;
 92	        field.place(this, newLocation);
 93	    }
