104	    /**
105	     * Create new creatures into free adjacent locations.
106	     */
107	    protected void createAdjacentCreatures(List<Creature> newCreatures, int count, CreatureFactory factory)
108	    {
109	        List<Location> freeLocations = field.getFreeAdjacentLocations(location);
110	        for(int created = 0; created < count && !freeLocations.isEmpty(); created++) {
111	            Location where = freeLocations.remove(0);
112	            newCreatures.add(factory.create(field, where));
113	        }
114	    }
