 24	    private static final Random rand = Randomizer.getRandom();
 25	    // The amount of oxygen a plant need to survive in night.
 26	    private static final double PLANT_OXYGEN_REQUIRED = 0.00000002;
 27	    // The amount of oxygen a plant generated during day time.
