 61	        if(oxygenLevel < PLANT_OXYGEN_REQUIRED){
 62	            setDead();
 63	            return 0;
 64	        }    
 65	        
 66	       
 67	        if(isAlive()){
 68	            if(age >= MATURE_AGE)
 69	                giveBirth(newSeaweeds);            
 70	            }
 71	        
 72	        
 73	        if(atDayTime)
 74	            return OXYGEN_GENERATED;
 75	        else
 76	            return -PLANT_OXYGEN_REQUIRED;
 77	        }
