  4	/**
  5	 * This class collects and provides some statistical data on the state 
  6	 * of a field. It is flexible: it will create and maintain a counter 
  7	 * for any class of object that is found within the field.
  8	 *
  9	 * @version 2022/03/02
 10	 */
 11	public class FieldStats
 12	{
 13	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
 14	    private Map<Class<?>, Counter> counters;
 15	    // Whether the counters are currently up to date.
 16	    private boolean countsValid;
 17	
 18	    /**
 19	     * Construct a FieldStats object.
 20	     */
 21	    public FieldStats()
 22	    {
 23	        // Set up a collection for counters for each type of animal that
 24	        // we might find
 25	        counters = new HashMap<>();
 26	        countsValid = true;
 27	    }
 28	
 29	    /**
 30	     * Get details of what is in the field.
 31	     * @return A string describing what is in the field.
 32	     */
 33	    public String getPopulationDetails(Field field)
 34	    {
 35	        StringBuilder buffer = new StringBuilder();
 36	        if(!countsValid) {
 37	            generateCounts(field);
 38	        }
 39	        for(Map.Entry<Class<?>, Counter> entry : counters.entrySet()) {
 40	            Counter info = entry.getValue();
 41	            buffer.append(info.getName());
 42	            buffer.append(": ");
 43	            buffer.append(info.getCount());
 44	            buffer.append(' ');
 45	        }
 46	        return buffer.toString();
 47	    }
 48	    
 49	    /**
 50	     * Invalidate the current set of statistics; reset all 
 51	     * counts to zero.
 52	     */
 53	    public void reset()
 54	    {
 55	        countsValid = false;
 56	        for(Class<?> key : counters.keySet()) {
 57	            Counter count = counters.get(key);
 58	            count.reset();
 59	        }
 60	    }
 61	    
 62	    
 63	
 64	    /**
 65	     * Increment the count for one class of animal.
 66	     * @param animalClass The class of animal to increment.
 67	     */
 68	    public void incrementCount(Class<?> animalClass)
 69	    {
 70	        Counter count = counters.get(animalClass);
 71	        if(count == null) {
 72	            // We do not have a counter for this species yet.
 73	            // Create one.
 74	            count = new Counter(animalClass.getName());
 75	            counters.put(animalClass, count);
 76	        }
 77	        count.increment();
 78	    }
 79	
 80	    /**
 81	     * Indicate that an animal count has been completed.
 82	     */
 83	    public void countFinished()
 84	    {
 85	        countsValid = true;
 86	    }
