109	    /**
110	     * Generate counts of the number of foxes and rabbits.
111	     * These are not kept up to date as foxes and rabbits
112	     * are placed in the field, but only when a rrandomAdjacentLocationequest
113	     * is made for the information.
114	     * @param field The field to generate the stats for.
115	     */
116	    private void generateCounts(Field field)
117	    {
118	        reset();
119	        for(int row = 0; row < field.getDepth(); row++) {
120	            for(int col = 0; col < field.getWidth(); col++) {
121	                Creature animal = field.getCreatureAt(row, col);
122	                if(animal != null) {
123	                    incrementCount(animal.getClass());
124	                }
125	            }
126	        }
127	        countsValid = true;
128	    }
129	}
